<div class="wp-block-wdl-fv-2 fv-2 min-h-pc-300px min-h-tb-260px min-h-sp-180px"><h1 class="ttl" style="color:#ffffff">相続のよくあるご質問</h1><div class="filter" style="background-color:#1a1d21;opacity:1"></div><style>
                        .fv-2 h1:after {
                            background: #8a7343;
                        }
                    </style></div>
