<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}},"align":"center"} -->
<p class="has-text-align-center has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">よくある質問の一覧ではありません。<strong>お答えに時間のかかる5つ</strong>だけを、1問ずつ書いています。読む順番は決まっていません。気になるものから開いてください。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#1a1d21"},"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#1a1d21;font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">5つの問い</h3>
<!-- /wp:heading -->
<!-- wp:wdl/lw-link-list-1 {"MaxWidth":900,"BtnGap":12,"BtnClm":1,"BtnClmSp":1,"backgroundSwitch":false,"hideTitle":true,"colorLiSvg":"#ffffff","colorLiBg":"#1a1d21","colorLiText":"#ffffff","colorLiBorder":"#8a7343","ListBorderSize":1,"ListBorderRadius":2} -->
<div class="wp-block-wdl-lw-link-list-1 lw-link-list-1 bg_hidden"><ul class="lw-link-list-1__inner clm_1 clm_sp_1" style="gap:12px;max-width:900px"><li class="lw-link-list-1__li"><a href="#q1" class="lw-link-list-1__link" style="border-radius:2px;border:1px solid #8a7343" target="_blank" rel="noopener noreferrer"><div class="btn_bg_color" style="background-color:#1a1d21;opacity:100%"></div><span class="lw-link-list-1__text" data-lw_font_set=""><p style="color:#ffffff">① 何から手をつければいいですか</p></span></a></li><li class="lw-link-list-1__li"><a href="#q2" class="lw-link-list-1__link" style="border-radius:2px;border:1px solid #8a7343" target="_blank" rel="noopener noreferrer"><div class="btn_bg_color" style="background-color:#1a1d21;opacity:100%"></div><span class="lw-link-list-1__text" data-lw_font_set=""><p style="color:#ffffff">② いつまでに終わらせる必要がありますか</p></span></a></li><li class="lw-link-list-1__li"><a href="#q3" class="lw-link-list-1__link" style="border-radius:2px;border:1px solid #8a7343" target="_blank" rel="noopener noreferrer"><div class="btn_bg_color" style="background-color:#1a1d21;opacity:100%"></div><span class="lw-link-list-1__text" data-lw_font_set=""><p style="color:#ffffff">③ 兄弟の意見が合いません</p></span></a></li><li class="lw-link-list-1__li"><a href="#q4" class="lw-link-list-1__link" style="border-radius:2px;border:1px solid #8a7343" target="_blank" rel="noopener noreferrer"><div class="btn_bg_color" style="background-color:#1a1d21;opacity:100%"></div><span class="lw-link-list-1__text" data-lw_font_set=""><p style="color:#ffffff">④ 家しか財産がありません</p></span></a></li><li class="lw-link-list-1__li"><a href="#q5" class="lw-link-list-1__link" style="border-radius:2px;border:1px solid #8a7343" target="_blank" rel="noopener noreferrer"><div class="btn_bg_color" style="background-color:#1a1d21;opacity:100%"></div><span class="lw-link-list-1__text" data-lw_font_set=""><p style="color:#ffffff">⑤ 費用はいくらかかりますか</p></span></a></li></ul><div class="lw-link-list-1__filter" style="background:var(--color-main);opacity:0.9"></div></div>
<!-- /wp:wdl/lw-link-list-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/custom-title-5 {"subTitle":"QUESTION 01","mainTitle":"何から手をつけますか","headingLevel":2,"mainTitleColor":"#8a7343","fontSize":"m"} -->
<h2 class="wp-block-wdl-custom-title-5 custom-title-5 font_size_m" style="border-color:#8a7343" id="q1"><span class="sub" style="color:#8a7343">QUESTION 01</span><span class="main">何から手をつけますか</span></h2>
<!-- /wp:wdl/custom-title-5 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">いちばん多いご質問です。答えは「<strong>相続人が誰かを確定させること</strong>」から、になります。遺産の中身を調べるのは、そのあとで構いません。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">順番が逆になると、あとから知らない相続人が出てきて、話し合いをやり直すことになります。実際、当事務所で扱った件の1割ほどで、ご家族が把握していない相続人が見つかっています。前の結婚のお子さん、認知されたお子さん、亡くなった兄弟の子。どれも珍しいことではありません。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">確定させるには、亡くなった方の出生から死亡までの戸籍をすべて集めます。本籍を何度も移されている方だと、5〜8か所の役所に請求することになり、ご自身でされると1〜2か月かかります。ここだけをお任せいただくこともできます。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-waku-1 {"waku1MaxWidthPc":940,"waku1PaddingTopPc":28,"waku1PaddingBottomPc":28,"waku1PaddingLeftPc":32,"waku1PaddingRightPc":32,"waku1PaddingTopSp":20,"waku1PaddingBottomSp":20,"waku1PaddingLeftSp":16,"waku1PaddingRightSp":16,"waku1BorderWidthPc":1,"waku1BorderColorPc":"#8a7343","waku1BorderRadiusPc":[8,8,8,8],"waku1BgColorPc":"#f2f3f5"} -->
<div class="wp-block-wdl-lw-pr-waku-1 lw-pr-waku-1" style="--waku-1-justify-content-pc:center;--waku-1-justify-content-sp:center"><div class="lw-pr-waku-1__custom_wrap" style="--waku-1-max-width-pc:940px;--waku-1-max-width-sp:940px;--waku-1-padding-pc:28px 32px 28px 32px;--waku-1-padding-sp:20px 16px 20px 16px;--waku-1-bd-width-pc:1px;--waku-1-bd-width-sp:1px;--waku-1-bd-style-pc:solid;--waku-1-bd-style-sp:solid;--waku-1-bd-color-pc:#8a7343;--waku-1-bd-color-sp:#8a7343;--waku-1-bdr-pc:8px 8px 8px 8px;--waku-1-bdr-sp:8px 8px 8px 8px;--waku-1-bg-pc:#f2f3f5;--waku-1-bg-sp:#f2f3f5;--waku-1-bg-opacity-pc:1;--waku-1-bg-opacity-sp:1;--waku-1-blend-mode-pc:normal;--waku-1-blend-mode-sp:normal;--waku-1-bg-img-pc:none;--waku-1-bg-img-sp:none;--waku-1-img-filter-pc:none;--waku-1-img-filter-sp:none;--waku-1-min-height-pc:auto;--waku-1-min-height-sp:auto;--waku-1-aspect-ratio-pc:auto;--waku-1-aspect-ratio-sp:auto"><!-- wp:heading {"level":3,"style":{"color":{"text":"#1a1d21"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"12px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#1a1d21;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:12px">この問いの要点</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:0px;margin-bottom:0px"><strong>まず戸籍を集める。</strong>財産調べは後でよい</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">出生から死亡まで、すべての戸籍が要る（本籍を移していると5〜8か所）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">ここだけのご依頼も承ります（実費のほか 33,000円）</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-waku-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/custom-title-5 {"subTitle":"QUESTION 02","mainTitle":"いつまでに終わらせる必要がありますか","headingLevel":2,"mainTitleColor":"#8a7343","fontSize":"m"} -->
<h2 class="wp-block-wdl-custom-title-5 custom-title-5 font_size_m" style="border-color:#8a7343" id="q2"><span class="sub" style="color:#8a7343">QUESTION 02</span><span class="main">いつまでに終わらせる必要がありますか</span></h2>
<!-- /wp:wdl/custom-title-5 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9"><strong>期限があるのは3つだけ</strong>です。それ以外に急ぐ理由はありません。「早く決めないと」と急かされているとしたら、その方の都合かもしれません。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">1つめは相続放棄で、亡くなったことを知った日から3か月です。借金があるかもしれないときは、この3か月がいちばん大事になります。調べきれないときは、家庭裁判所に期間を延ばしてもらえます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">2つめは所得税の準確定申告で4か月、3つめは相続税の申告で10か月です。ただし相続税は、基礎控除（3,000万円＋600万円×相続人の数）を超えなければ申告そのものが要りません。実際に申告が必要になるのは、亡くなった方100人のうち9人ほどです。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">なお、<strong>不動産の名義変更は2024年4月から義務</strong>になりました。知った日から3年以内です。過去の相続にもさかのぼって適用されます。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-waku-1 {"waku1MaxWidthPc":940,"waku1PaddingTopPc":28,"waku1PaddingBottomPc":28,"waku1PaddingLeftPc":32,"waku1PaddingRightPc":32,"waku1PaddingTopSp":20,"waku1PaddingBottomSp":20,"waku1PaddingLeftSp":16,"waku1PaddingRightSp":16,"waku1BorderWidthPc":1,"waku1BorderColorPc":"#8a7343","waku1BorderRadiusPc":[8,8,8,8],"waku1BgColorPc":"#f2f3f5"} -->
<div class="wp-block-wdl-lw-pr-waku-1 lw-pr-waku-1" style="--waku-1-justify-content-pc:center;--waku-1-justify-content-sp:center"><div class="lw-pr-waku-1__custom_wrap" style="--waku-1-max-width-pc:940px;--waku-1-max-width-sp:940px;--waku-1-padding-pc:28px 32px 28px 32px;--waku-1-padding-sp:20px 16px 20px 16px;--waku-1-bd-width-pc:1px;--waku-1-bd-width-sp:1px;--waku-1-bd-style-pc:solid;--waku-1-bd-style-sp:solid;--waku-1-bd-color-pc:#8a7343;--waku-1-bd-color-sp:#8a7343;--waku-1-bdr-pc:8px 8px 8px 8px;--waku-1-bdr-sp:8px 8px 8px 8px;--waku-1-bg-pc:#f2f3f5;--waku-1-bg-sp:#f2f3f5;--waku-1-bg-opacity-pc:1;--waku-1-bg-opacity-sp:1;--waku-1-blend-mode-pc:normal;--waku-1-blend-mode-sp:normal;--waku-1-bg-img-pc:none;--waku-1-bg-img-sp:none;--waku-1-img-filter-pc:none;--waku-1-img-filter-sp:none;--waku-1-min-height-pc:auto;--waku-1-min-height-sp:auto;--waku-1-aspect-ratio-pc:auto;--waku-1-aspect-ratio-sp:auto"><!-- wp:heading {"level":3,"style":{"color":{"text":"#1a1d21"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"12px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#1a1d21;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:12px">この問いの要点</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:0px;margin-bottom:0px">相続放棄 … 3か月（延ばせます）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">準確定申告 … 4か月</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">相続税の申告 … 10か月（基礎控除を超えたときだけ）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">不動産の名義変更 … 3年（2024年4月から義務）</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-waku-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/custom-title-5 {"subTitle":"QUESTION 03","mainTitle":"兄弟の意見が合いません","headingLevel":2,"mainTitleColor":"#8a7343","fontSize":"m"} -->
<h2 class="wp-block-wdl-custom-title-5 custom-title-5 font_size_m" style="border-color:#8a7343" id="q3"><span class="sub" style="color:#8a7343">QUESTION 03</span><span class="main">兄弟の意見が合いません</span></h2>
<!-- /wp:wdl/custom-title-5 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">この場合、<strong>当事務所は代理人にはなれません</strong>。司法書士・行政書士は、争いのある案件でどちらか一方の側に立つことができない決まりです。これは能力の問題ではなく、法律で決まっていることです。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">できることは2つあります。1つは、全員の同意ができた前提での書類作成。もう1つは、<strong>争いになる前の整理</strong>です。「何がいくらあるか」「法律ではどう分けることになっているか」を、全員に同じ資料でお見せするだけで、話がまとまることが実際によくあります。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">すでに感情のもつれがある場合は、弁護士をご紹介します。紹介料はいただきません。ご自身で探されても構いません。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-waku-1 {"waku1MaxWidthPc":940,"waku1PaddingTopPc":28,"waku1PaddingBottomPc":28,"waku1PaddingLeftPc":32,"waku1PaddingRightPc":32,"waku1PaddingTopSp":20,"waku1PaddingBottomSp":20,"waku1PaddingLeftSp":16,"waku1PaddingRightSp":16,"waku1BorderWidthPc":1,"waku1BorderColorPc":"#8a7343","waku1BorderRadiusPc":[8,8,8,8],"waku1BgColorPc":"#f2f3f5"} -->
<div class="wp-block-wdl-lw-pr-waku-1 lw-pr-waku-1" style="--waku-1-justify-content-pc:center;--waku-1-justify-content-sp:center"><div class="lw-pr-waku-1__custom_wrap" style="--waku-1-max-width-pc:940px;--waku-1-max-width-sp:940px;--waku-1-padding-pc:28px 32px 28px 32px;--waku-1-padding-sp:20px 16px 20px 16px;--waku-1-bd-width-pc:1px;--waku-1-bd-width-sp:1px;--waku-1-bd-style-pc:solid;--waku-1-bd-style-sp:solid;--waku-1-bd-color-pc:#8a7343;--waku-1-bd-color-sp:#8a7343;--waku-1-bdr-pc:8px 8px 8px 8px;--waku-1-bdr-sp:8px 8px 8px 8px;--waku-1-bg-pc:#f2f3f5;--waku-1-bg-sp:#f2f3f5;--waku-1-bg-opacity-pc:1;--waku-1-bg-opacity-sp:1;--waku-1-blend-mode-pc:normal;--waku-1-blend-mode-sp:normal;--waku-1-bg-img-pc:none;--waku-1-bg-img-sp:none;--waku-1-img-filter-pc:none;--waku-1-img-filter-sp:none;--waku-1-min-height-pc:auto;--waku-1-min-height-sp:auto;--waku-1-aspect-ratio-pc:auto;--waku-1-aspect-ratio-sp:auto"><!-- wp:heading {"level":3,"style":{"color":{"text":"#1a1d21"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"12px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#1a1d21;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:12px">この問いの要点</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:0px;margin-bottom:0px">争いのある案件は<strong>お引き受けできません</strong>（法律の決まり）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">「全員に同じ資料を見せる」だけで収まることは多い</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">弁護士をご紹介します。紹介料はいただきません</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-waku-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/custom-title-5 {"subTitle":"QUESTION 04","mainTitle":"家しか財産がありません","headingLevel":2,"mainTitleColor":"#8a7343","fontSize":"m"} -->
<h2 class="wp-block-wdl-custom-title-5 custom-title-5 font_size_m" style="border-color:#8a7343" id="q4"><span class="sub" style="color:#8a7343">QUESTION 04</span><span class="main">家しか財産がありません</span></h2>
<!-- /wp:wdl/custom-title-5 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">もっとも多いご相談です。相続で揉める件の3分の1は、<strong>財産が家1つ</strong>という状況で起きています。分けようがないためです。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">取りうる道は4つです。①1人が住み続け、他の方に現金を渡す（代償分割）②売って現金で分ける（換価分割）③共有のままにする ④誰も住まずに空き家にする。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">このうち<strong>③の共有はお勧めしません</strong>。そのときは平等に見えますが、次の代でさらに人数が増え、売ることも貸すこともできなくなります。10年後・20年後に困るのは、いま決めた方ではなくお子さんです。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">④も同じです。空き家のまま持ち続けると、固定資産税が最大6倍になることがあります（管理されていない空き家と判断された場合）。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-waku-1 {"waku1MaxWidthPc":940,"waku1PaddingTopPc":28,"waku1PaddingBottomPc":28,"waku1PaddingLeftPc":32,"waku1PaddingRightPc":32,"waku1PaddingTopSp":20,"waku1PaddingBottomSp":20,"waku1PaddingLeftSp":16,"waku1PaddingRightSp":16,"waku1BorderWidthPc":1,"waku1BorderColorPc":"#8a7343","waku1BorderRadiusPc":[8,8,8,8],"waku1BgColorPc":"#f2f3f5"} -->
<div class="wp-block-wdl-lw-pr-waku-1 lw-pr-waku-1" style="--waku-1-justify-content-pc:center;--waku-1-justify-content-sp:center"><div class="lw-pr-waku-1__custom_wrap" style="--waku-1-max-width-pc:940px;--waku-1-max-width-sp:940px;--waku-1-padding-pc:28px 32px 28px 32px;--waku-1-padding-sp:20px 16px 20px 16px;--waku-1-bd-width-pc:1px;--waku-1-bd-width-sp:1px;--waku-1-bd-style-pc:solid;--waku-1-bd-style-sp:solid;--waku-1-bd-color-pc:#8a7343;--waku-1-bd-color-sp:#8a7343;--waku-1-bdr-pc:8px 8px 8px 8px;--waku-1-bdr-sp:8px 8px 8px 8px;--waku-1-bg-pc:#f2f3f5;--waku-1-bg-sp:#f2f3f5;--waku-1-bg-opacity-pc:1;--waku-1-bg-opacity-sp:1;--waku-1-blend-mode-pc:normal;--waku-1-blend-mode-sp:normal;--waku-1-bg-img-pc:none;--waku-1-bg-img-sp:none;--waku-1-img-filter-pc:none;--waku-1-img-filter-sp:none;--waku-1-min-height-pc:auto;--waku-1-min-height-sp:auto;--waku-1-aspect-ratio-pc:auto;--waku-1-aspect-ratio-sp:auto"><!-- wp:heading {"level":3,"style":{"color":{"text":"#1a1d21"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"12px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#1a1d21;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:12px">この問いの要点</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:0px;margin-bottom:0px">①代償分割 … 1人が住み、他の方へ現金を渡す</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">②換価分割 … 売って現金で分ける</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px"><strong>③共有はお勧めしません</strong>。次の代で動かせなくなります</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">④空き家のまま … 固定資産税が最大6倍になることがあります</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-waku-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/custom-title-5 {"subTitle":"QUESTION 05","mainTitle":"費用はいくらかかりますか","headingLevel":2,"mainTitleColor":"#8a7343","fontSize":"m"} -->
<h2 class="wp-block-wdl-custom-title-5 custom-title-5 font_size_m" style="border-color:#8a7343" id="q5"><span class="sub" style="color:#8a7343">QUESTION 05</span><span class="main">費用はいくらかかりますか</span></h2>
<!-- /wp:wdl/custom-title-5 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">当事務所の報酬は、<strong>件数ではなく作業の量</strong>で決めています。相続人が3名・不動産1件・預金2口座、という一般的な場合で、報酬は 165,000円ほどです。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">これとは別に、実費がかかります。登録免許税（不動産の評価額の0.4％）、戸籍の取り寄せ（1通450〜750円）、登記事項証明書（1通600円）などです。評価額1,500万円の家なら登録免許税は6万円ほどになります。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9"><strong>お見積りは着手前に、書面でお出しします。</strong>あとから増えることはありません。増えるとしたら、「知らない相続人が見つかった」など前提が変わったときだけで、そのときは必ず先にご相談します。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9">初回のご相談は無料です。1時間ほどお話をうかがって、その場で「ご自身でできそうか」「頼んだほうが早いか」をお伝えします。<strong>ご自身でできる場合は、そう申し上げます。</strong></p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-waku-1 {"waku1MaxWidthPc":940,"waku1PaddingTopPc":28,"waku1PaddingBottomPc":28,"waku1PaddingLeftPc":32,"waku1PaddingRightPc":32,"waku1PaddingTopSp":20,"waku1PaddingBottomSp":20,"waku1PaddingLeftSp":16,"waku1PaddingRightSp":16,"waku1BorderWidthPc":1,"waku1BorderColorPc":"#8a7343","waku1BorderRadiusPc":[8,8,8,8],"waku1BgColorPc":"#f2f3f5"} -->
<div class="wp-block-wdl-lw-pr-waku-1 lw-pr-waku-1" style="--waku-1-justify-content-pc:center;--waku-1-justify-content-sp:center"><div class="lw-pr-waku-1__custom_wrap" style="--waku-1-max-width-pc:940px;--waku-1-max-width-sp:940px;--waku-1-padding-pc:28px 32px 28px 32px;--waku-1-padding-sp:20px 16px 20px 16px;--waku-1-bd-width-pc:1px;--waku-1-bd-width-sp:1px;--waku-1-bd-style-pc:solid;--waku-1-bd-style-sp:solid;--waku-1-bd-color-pc:#8a7343;--waku-1-bd-color-sp:#8a7343;--waku-1-bdr-pc:8px 8px 8px 8px;--waku-1-bdr-sp:8px 8px 8px 8px;--waku-1-bg-pc:#f2f3f5;--waku-1-bg-sp:#f2f3f5;--waku-1-bg-opacity-pc:1;--waku-1-bg-opacity-sp:1;--waku-1-blend-mode-pc:normal;--waku-1-blend-mode-sp:normal;--waku-1-bg-img-pc:none;--waku-1-bg-img-sp:none;--waku-1-img-filter-pc:none;--waku-1-img-filter-sp:none;--waku-1-min-height-pc:auto;--waku-1-min-height-sp:auto;--waku-1-aspect-ratio-pc:auto;--waku-1-aspect-ratio-sp:auto"><!-- wp:heading {"level":3,"style":{"color":{"text":"#1a1d21"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"12px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#1a1d21;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:12px">この問いの要点</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:0px;margin-bottom:0px">報酬 … 一般的な場合で 165,000円ほど（作業の量で決めます）</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">実費 … 登録免許税（評価額の0.4％）・戸籍・証明書</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">見積りは着手前に書面で。あとから増えません</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2f3338"},"typography":{"fontSize":"16px","lineHeight":"1.9"},"spacing":{"margin":{"top":"14px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#2f3338;font-size:16px;line-height:1.9;margin-top:14px;margin-bottom:0px">初回のご相談は無料。ご自身でできる場合はそう申し上げます</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-waku-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-bg-1 {"backgroundType":"image","imagePc":"","imageSp":"","isFullWidth":true,"maxWidth":1040,"minHeightPc":"min-h-pc-150px","minHeightTb":"min-h-tb-160px","minHeightSp":"min-h-sp-160px","innerPaddingTopPc":80,"innerPaddingBottomPc":80,"innerPaddingLeftPc":40,"innerPaddingRightPc":40,"innerPaddingTopTb":64,"innerPaddingBottomTb":64,"innerPaddingLeftTb":32,"innerPaddingRightTb":32,"innerPaddingTopSp":48,"innerPaddingBottomSp":48,"innerPaddingLeftSp":20,"innerPaddingRightSp":20,"filterTypePc":"solid","filterColorPc":"#1a1d21","opacityPc":1,"filterTypeTb":"solid","filterColorTb":"#1a1d21","opacityTb":1,"filterTypeSp":"solid","filterColorSp":"#1a1d21","opacitySp":1} -->
