<h3 class="has-text-align-center has-text-color" style="color:#ffffff;font-size:24px;line-height:1.6;margin-top:0px;margin-bottom:16px">ここに無いことは、1時間の無料相談で</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#ffffff"},"typography":{"fontSize":"16px","lineHeight":"1.9"}},"align":"center"} -->
<p class="has-text-align-center has-text-color" style="color:#ffffff;font-size:16px;line-height:1.9">何も決まっていない状態で構いません。書類もお持ちでなくて結構です。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
